import type { StyleSpecification } from '@maplibre/maplibre-react-native';

import { env } from '@/config/env';
import type { ColorScheme } from '@/theme';

import dark from './styles/dark.json';
import light from './styles/light.json';

const PLACEHOLDER = '__MAP_URL__';
const templates: Record<ColorScheme, unknown> = { light, dark };
const cache = new Map<string, StyleSpecification>();

/**
 * The map style for a colour scheme, pointing at the self-hosted map server. Generated by
 * scripts/build-map-styles.mjs; only the server address is filled in here.
 */
export function mapStyle(scheme: ColorScheme, mapUrl: string = env.mapUrl): StyleSpecification {
  const key = `${scheme}|${mapUrl}`;
  const cached = cache.get(key);
  if (cached !== undefined) return cached;
  const style = JSON.parse(
    JSON.stringify(templates[scheme]).replaceAll(PLACEHOLDER, mapUrl),
  ) as StyleSpecification;
  cache.set(key, style);
  return style;
}

/** Where the map opens before the user's position is known: all of Turkey. */
export const INITIAL_VIEW = { center: [35.2, 39.0] as [number, number], zoom: 4.6 };
/** Zoom once the user's position is known: the neighbourhood, streets readable. */
export const FOCUS_ZOOM = 14;
